'''})
    r = invoke(tmp_path, ".")
    assert r.returncode == 1
    assert len(r.stdout.splitlines()) == 2


def test_recursive_packages_and_multiple_files(tmp_path):
    project(tmp_path, {
        "go.mod": "module example.com/m\ngo 1.20\n",
        "a.go": "package main\nfunc main() { f() }\n",
        "b.go": "package main\nfunc f() error{return nil}\n",
        "deep/p/p.go": "package p\nimport \"os\"\nfunc F(){os.Open(\"x\")}\n",
    })
    r = invoke(tmp_path, "./...")
    assert r.returncode == 1
    assert "a.go:2:" in r.stdout and "deep/p/p.go:3:" in r.stdout


